//! Regression coverage for FMS/UFS history files (e.g. `atmf024.nc`) whose
//! `DIMENSION_LIST` uses the vlen-of-object-references encoding the low-level
//! reader cannot decode. Variables then report phony dimension names while
//! `_Netcdf4Coordinates`/`_Netcdf4Dimid` remain valid, and axis roles must
//! still be recovered from the 1-D coordinate variables (`cartesian_axis`,
//! `positive`, `units`). Without those roles the interactive level stepper
//! collapses to a single level and the level list stays empty.
//!
//! The committed fixture is generated by `tools/generate_fms_vlen_fixture.py`.

use ncview_rs::data::slice::{Bounds, SliceRequest};
use ncview_rs::data::{AxisRole, DataSource};

const FIXTURE: &str = "tests/fixtures/fms-vlen-dimlist.nc4";

fn open_fixture() -> Box<dyn DataSource> {
    ncview_rs::data::open(FIXTURE).expect("fixture opens")
}

#[test]
fn coordinate_roles_are_promoted_when_dimension_lists_are_unreadable() {
    let source = open_fixture();
    let metadata = source.metadata();
    let role = |name: &str| {
        metadata
            .dimensions
            .iter()
            .find(|dimension| dimension.name == name)
            .unwrap_or_else(|| panic!("missing dimension {name}: {:?}", metadata.dimensions))
            .role
    };
    assert_eq!(role("pfull"), AxisRole::Depth);
    assert_eq!(role("phalf"), AxisRole::Depth);
    assert_eq!(role("grid_yt"), AxisRole::Latitude);
    assert_eq!(role("grid_xt"), AxisRole::Longitude);
    assert_eq!(role("time"), AxisRole::Time);
    let tmp = metadata
        .variables
        .iter()
        .find(|variable| variable.name == "tmp")
        .expect("tmp variable");
    assert_eq!(tmp.dimensions, ["time", "pfull", "grid_yt", "grid_xt"]);
}

#[test]
fn every_level_has_a_label_and_a_distinct_slice() {
    let source = open_fixture();
    let labels = source.vertical_labels("tmp");
    assert_eq!(labels.len(), 3, "level list must cover pfull: {labels:?}");
    assert!(labels[1].contains("500"), "labels={labels:?}");
    assert!(labels[2].contains("1000"), "labels={labels:?}");
    for level in 0..3usize {
        let slice = source
            .read_slice(&SliceRequest {
                variable: "tmp".into(),
                time: 0,
                depth: level,
                bounds: Bounds::new(0, 3, 0, 4).unwrap(),
            })
            .unwrap_or_else(|error| panic!("level {level}: {error}"));
        for row in 0..3 {
            for col in 0..4 {
                assert_eq!(
                    slice.value_at_source(row, col),
                    Some((level * 100 + row * 4 + col) as f64),
                    "level {level} row {row} col {col}"
                );
            }
        }
        let label = source
            .vertical_label("tmp", level)
            .unwrap_or_else(|| panic!("missing label for level {level}"));
        assert!(label.contains(&format!("index {level}")), "label={label}");
    }
}

#[test]
fn level_navigation_reads_the_selected_plane_through_explicit_axes() {
    // Mirrors the interactive reload path: explicit display axes plus fixed
    // time/depth indices chosen from the promoted dimension roles.
    let source = open_fixture();
    for level in [2usize, 0, 1] {
        let slice = source
            .read_slice_on_axes(
                &SliceRequest {
                    variable: "tmp".into(),
                    time: 0,
                    depth: level,
                    bounds: Bounds::new(0, 3, 0, 4).unwrap(),
                },
                Some("grid_yt"),
                Some("grid_xt"),
                &[("time".into(), 0), ("pfull".into(), level)],
            )
            .unwrap_or_else(|error| panic!("level {level}: {error}"));
        assert_eq!(
            slice.value_at_source(2, 3),
            Some((level * 100 + 11) as f64),
            "level {level}"
        );
    }
}

#[test]
fn dimension_values_resolve_canonical_level_coordinates() {
    let source = open_fixture();
    let values = source
        .dimension_values("tmp", "pfull")
        .expect("pfull coordinate values");
    assert_eq!(values, vec![100.0, 500.0, 1000.0]);
}
